effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat20;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.xyz = max(u_xlat0.xyz, vec3(0.0, 0.0, 0.0));
    u_xlat1.xyz = log2(u_xlat1.xyz);
    u_xlat1.xyz = u_xlat1.xyz * vec3(0.416666657, 0.416666657, 0.416666657);
    u_xlat1.xyz = exp2(u_xlat1.xyz);
    u_xlat1.xyz = u_xlat1.xyz * vec3(1.05499995, 1.05499995, 1.05499995) + vec3(-0.0549999997, -0.0549999997, -0.0549999997);
    u_xlat1.yzw = max(u_xlat1.xyz, vec3(0.0, 0.0, 0.0));
    u_xlat2.xyz = u_xlat0.xyz * vec3(5.55555582, 5.55555582, 5.55555582) + vec3(0.0479959995, 0.0479959995, 0.0479959995);
    u_xlat2.xyz = log2(u_xlat2.xyz);
    u_xlat2.yzw = u_xlat2.xyz * vec3(0.0734997839, 0.0734997839, 0.0734997839) + vec3(0.386036009, 0.386036009, 0.386036009);
    u_xlat2.yzw = clamp(u_xlat2.yzw, 0.0, 1.0);
    u_xlat2.x = u_xlat0.w * _PostExposure;
    u_xlat1.x = u_xlat0.w;
    u_xlat1 = (int(_lut_space) != 0) ? u_xlat1.yzwx : u_xlat2.yzwx;
    u_xlat2.xyz = u_xlat1.xyz * _Lut3D_Params.yyy;
    u_xlat20 = _Lut3D_Params.x * 0.5;
    u_xlat2.xyz = u_xlat2.xyz * _Lut3D_Params.xxx + vec3(u_xlat20);
    u_xlat2.xyz = texture(Lut3D, u_xlat2.xyz).xyz;
    u_xlat3.xyz = u_xlat2.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat3.xyz = u_xlat2.xyz * u_xlat3.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat3.xyz = u_xlat2.xyz * u_xlat3.xyz;
    u_xlat1.xyz = (int(_lut_space) != 0) ? u_xlat3.xyz : u_xlat2.xyz;
    u_xlat1 = (-u_xlat0) + u_xlat1;
    u_xlat1 = vec4(_blend) * u_xlat1 + u_xlat0;
    if(_use_inner_mask != 0) {
        u_xlatb2.xy = equal(ivec4(_show_inner_mask, _b_clip_mask, _show_inner_mask, _show_inner_mask), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
